end)()
    local go = UnityEngine.GameObject("dr_desktop_bgm")
    -- UI visibility and UI error recovery must not deactivate the music source.
    -- OnDestroy explicitly disposes this independent scene object.
    local source = go:AddComponent(typeof(UnityEngine.AudioSource))
    source.playOnAwake = false
    source.spatialBlend = 0
    source.loop = true
    source.volume = 0.65
    source.priority = 0
    source.dopplerLevel = 0
    source.ignoreListenerPause = true
    local clip = UnityEngine.AudioClip.Create("dragonrest_theme", data.frames, data.channels, data.rate, false)
    return { go = go, source = source, clip = clip, data = data, chunk = 1, offset = 0 }
end

function M.update(state)
    if state.data then
        -- Decode a bounded chunk each frame instead of blocking the title screen.
        local samples = M.decode(state.data.chunks[state.chunk])
        assert(state.clip:SetData(samples, state.offset), "background music SetData failed")
        state.offset = state.offset + #samples / state.data.channels
        state.chunk = state.chunk + 1
        if state.chunk > #state.data.chunks then
            state.data = nil
            state.source.clip = state.clip
            state.source:Play()
            CS.UnityEngine.Debug.LogError("[desktop_bgm] started: " .. tostring(state.clip.length) .. " seconds, loop=true")
        end
    elseif not state.verified and state.source.time > 1 then
        state.verified = true
        CS.UnityEngine.Debug.LogError("[desktop_bgm] verified playing=" .. tostring(state.source.isPlaying)
            .. " time=" .. tostring(state.source.time) .. " mute=" .. tostring(state.source.mute))
    end
    if UI.state == "play" or UI.state == "map" then state.fadeStarted=true end
    if state.fadeStarted then
        state.fadeElapsed=math.min(10,(state.fadeElapsed or 0)+UnityEngine.Time.unscaledDeltaTime)
        local t=state.fadeElapsed/10;local eased=t*t*(3-2*t)
        state.source.volume=.65+(.18-.65)*eased
    end
    if not state.data and UnityEngine.Time then
        state.auditT = (state.auditT or 0) + UnityEngine.Time.unscaledDeltaTime
        if state.auditT >= 5 then
            state.auditT = 0
            local now = state.source.time
            if not state.source.isPlaying or (state.lastTime and math.abs(now-state.lastTime)<.1) then
                CS.UnityEngine.Debug.LogError("[desktop_bgm] interruption playing=" .. tostring(state.source.isPlaying)
                    .. " time=" .. tostring(now) .. " active=" .. tostring(state.go.activeInHierarchy)
                    .. " focused=" .. tostring(UnityEngine.Application.isFocused))
            end
            state.lastTime=now
        end
    end
end

function M.dispose(state)
    if not state then return end
    if state.source then state.source:Stop() end
    if state.go then UnityEngine.Object.Destroy(state.go) end
    if state.clip then UnityEngine.Object.Destroy(state.clip) end
end

return M

end)()
        UI.desktopBgm = UI.desktopBgmModule.new(UI.root)
    end
    UI.desktopBgmModule.update(UI.desktopBgm)
end


function OnDestroy()
    for _,v in ipairs(UI.foliage.items or {}) do
        for _,b in ipairs(v.bends or {}) do UnityEngine.Object.Destroy(b.mesh) end
    end
    if DR.camera then UnityEngine.Object.Destroy(DR.camera.gameObject);DR.camera=nil end
    if DR.rider then pcall(function() DR.rider.gameObject.transform:SetParent(nil,true);DR.rider:StandUp(DR.seat);DR.rider:Immobilize(false) end);DR.rider=nil end
    if UI.desktopBgmModule then
        UI.desktopBgmModule.dispose(UI.desktopBgm)
        UI.desktopBgm = nil
    end
end

function Update()
    if UI.root == nil and not UI.failed then
        local okc, errc = pcall(UI.buildCanvas)
        if not okc then UI.failed = true; report("ui canvas failed " .. tostring(errc)) end
    end
    if not UI.desktopBgmDisabled then
        local okb, errb = pcall(UI.updateDesktopBgm)
        if not okb then
            UI.desktopBgmDisabled = true
            if UI.desktopBgmModule then pcall(UI.desktopBgmModule.dispose, UI.desktopBgm) end
            report("desktop music failed " .. tostring(errb))
        end
    end
    updateSky()
    if skyReady then UI.updateMotion() end
    if envReady and (castleMats == nil or #castleMats < 3) then
        castleRetry = castleRetry + Time.deltaTime
        if castleRetry > 1 then
            castleRetry = 0
            applyCastle(blend)
        end
    end
    if skyReady then
        updateFx()
    end
    if not DouyinNetService.isNetworkSettled then
        return
    end
    local actor = DouyinActorService.GetLocalActor()
    if actor == nil then
        return
    end
    if camState ~= "done" then
        updateSpawnCamera(actor)
    end
    if not UI.failed and UI.state ~= "off" then
        local oku, erru = pcall(UI.update, actor)
        if not oku then
            UI.failed = true
            report("ui failed " .. tostring(erru))
            pcall(function() UI.root:SetActive(false) end)
            pcall(UI.camEnd)
            pcall(UI.lockPlayer, actor, false)
        end
    end
    updateDayNight(actor)
    updatePortals(actor)
    if not UI.reeds.failed then
        local ok,err=pcall(UI.updateReeds,actor)
        if not ok then UI.reeds.failed=true;report("reeds failed "..tostring(err)) end
    end
    if not UI.foliage.failed then
        local ok,err=pcall(UI.updateFoliage,actor)
        if not ok then UI.foliage.failed=true;report("foliage failed "..tostring(err)) end
    end
    if detailMats == nil then
        detailRetry = (detailRetry or 0) - Time.deltaTime
        if detailRetry <= 0 then
            detailRetry = 1
            local okd, errd = pcall(setupDetail)
            if okd and errd then applyDetail(blend) elseif not okd then report("detail failed " .. tostring(errd)) end
        end
    end
    if lutParentRot == nil then
        buildLut()
        actor.speed = 4.5
    end
    local oks, errs = pcall(updateSites, actor)
    if not oks and not sitesFailed then
        sitesFailed = true
        report("sites failed " .. tostring(errs))
    end
    local okg, errg = pcall(updateGrass, actor)
    if not okg and not grassFailed then
        grassFailed = true
        report("grass failed " .. tostring(errg))
    end
    if DEBUG_TELEPORT then
        updateDebug(actor)
    end
end

function LateUpdate()
    if DR.v8 and DR.rider then DR.align(DR.rider) end
end

-- Narrow integration appended to the latest world script, not an old scene snapshot.
DR.phase1={scope=require("official.core.runtime_scope").from(self)}
function IsMounted()
 local a=DouyinActorService.GetLocalActor()
 return DR.rider~=nil or (a and (a:IsSitting()or a:IsFlying())) or false
end
function CanRideDragon()
 local p=DR.phase1.progress
 return p~=nil and p.CanRideDragon()
end
function GetBookTexture()return UI.tex and UI.tex.ui_book end
function GetExplorationState()return UI.state end
function ApplySavedClass(kind)
 local r,p=DR.phase1.rpg,DR.phase1.progress
 if r and p and p.IsLoaded()then r.SetProfile(p.GetProfile())end
end
function SetExplorationMenu(open)
 DR.phase1.menu=open
 local a=DouyinActorService.GetLocalActor();if a then UI.lockPlayer(a,open)end
end
function ReplayPrologue()
 if UI.P_book then UI.spread=1;UI.setSpread(1);UI.show(UI.P_book,true);UI.state='book';UI.st=UI.t
  local a=DouyinActorService.GetLocalActor();if a then UI.lockPlayer(a,true)end
 end
end
function SetSharedDay(day)if isDay~=day then setDay(day)end end
function GetWorldTime()return {day=isDay,elapsed=clock,duration=isDay and DAY_SECONDS or NIGHT_SECONDS}end
DR.phase1.originalUpdate=Update
function Update()
 DR.phase1.originalUpdate()
 UI.updateInkText()
 local s=DR.phase1
 if not s.rpg then s.rpg=s.scope:GetScript('dragon_rpg.lua')end
 if not s.progress then s.progress=s.scope:GetScript('dragon_progress.lua')end
 if beamGo then beamGo.progress=s.progress end
 if not s.rpg or not s.progress then return end
 local a=DouyinActorService.GetLocalActor();if not a then return end
 local playing=UI.state=='play'
 s.rpg.SetContext({menu=not playing or s.menu==true,mounted=IsMounted()})
 s.rpg.SetExplorationReady(playing and not s.menu and s.progress.IsLoaded())
 if playing and s.progress.IsLoaded()and not s.progress.GetProfile().class and not s.contract then
  s.contract=UI.showOath()
 end
end

-- Shared parchment artwork and real text controls.
UI.inkAssets={}
function GetInkTexture(key)
 if UI.inkAssets[key]then return UI.inkAssets[key]end
 local go=UnityEngine.GameObject.Find('InkCarrier_'..key)
 if not go then return nil end
 local r=go:GetComponentInChildren(typeof(UnityEngine.Renderer),true)
 if not r then return nil end
 local m=r.sharedMaterial;local t=nil
 for _,p in ipairs({'_BaseTex','_BaseMap','_MainTex'})do
  if not t and m:HasProperty(p)then t=m:GetTexture(p)end
 end
 if t then t.wrapMode=UnityEngine.TextureWrapMode.Clamp;UI.inkAssets[key]=t;r.enabled=false end
 return t
end
function GetMapEntrySprite()
 if UI.entrySprite then return UI.entrySprite end
 if not UI.tex or not UI.tex.ui_atlas or not UI.L then return nil end
 local r=UI.L.atlas.mapbtn;local t=UI.tex.ui_atlas
 UI.entrySprite=UnityEngine.Sprite.Create(t,UnityEngine.Rect(r[1]*t.width,r[2]*t.height,r[3]*t.width,r[4]*t.height),UI.V2(.5,.5),100)
 return UI.entrySprite
end
function GetInkFont()
 if UI.inkFont then return UI.inkFont end
 local fonts=UnityEngine.Resources.FindObjectsOfTypeAll(typeof(UnityEngine.Font))
 for i=0,fonts.Length-1 do if string.find(fonts[i].name,'WenKai')then UI.inkFont=fonts[i];return fonts[i]end end
 for i=0,fonts.Length-1 do if fonts[i].name=='NotoSansSC-Medium'then UI.inkFont=fonts[i];return fonts[i]end end
 return nil
end

