function ApplyInkText(t)
 if not t then return end
 UI.inkLabels[#UI.inkLabels+1]={text=t,glyphs={}}
end
function UI.updateInkText()
 local texture=GetInkTexture('font');if not texture or not UI.inkGlyphData or not UI.inkGlyphData.glyphs then return end
 for _,entry in ipairs(UI.inkLabels)do
  local t=entry.text
  if t and t.gameObject.activeInHierarchy then
   local w,h=t.rectTransform.rect.width,t.rectTransform.rect.height
   local key=t.text..':'..tostring(t.fontSize)..':'..tostring(w)..':'..tostring(h)..':'..tostring(t.color)
   if entry.key~=key then
    entry.key=key
    local scale=t.fontSize/48;local lines={{items={},width=0}};local line=lines[1]
    for ch in string.gmatch(t.text,'[%z\1-\127\194-\244][\128-\191]*')do
     local g=UI.inkGlyphData.glyphs[ch]
     if ch=='\n' then line={items={},width=0};lines[#lines+1]=line
     elseif g then
      local advance=g[2]*scale
      if line.width+advance>w and #line.items>0 then line={items={},width=0};lines[#lines+1]=line end
      line.items[#line.items+1]={g=g,x=line.width};line.width=line.width+advance
     end
    end
    local alignment=tostring(t.alignment);local top=string.find(alignment,'Upper')~=nil
    local left=string.find(alignment,'Left')~=nil;local right=string.find(alignment,'Right')~=nil
    local lineH=t.fontSize*1.48;local y=top and h/2-t.fontSize or #lines*lineH/2-t.fontSize
    local n=0
    for _,ln in ipairs(lines)do
     local x=left and -w/2 or (right and w/2-ln.width or -ln.width/2)
     for _,item in ipairs(ln.items)do
      n=n+1;local glyph=entry.glyphs[n]
      if not glyph then glyph=UI.img(t.transform,texture,nil,64*scale,64*scale,0,0);glyph.ri.raycastTarget=false;entry.glyphs[n]=glyph end
      local index=item.g[1];glyph.go:SetActive(true);glyph.rt.sizeDelta=UI.V2(64*scale,64*scale)
      glyph.rt.anchoredPosition=UI.V2(x+item.x+24*scale,y+20*scale)
      glyph.ri.uvRect=UnityEngine.Rect((index%UI.inkGlyphData.cols)/UI.inkGlyphData.cols,1-(math.floor(index/UI.inkGlyphData.cols)+1)/UI.inkGlyphData.rows,1/UI.inkGlyphData.cols,1/UI.inkGlyphData.rows)
      glyph.ri.color=t.color
     end
     y=y-lineH
    end
    t.enabled=n==0 and #t.text>0
    for i=n+1,#entry.glyphs do entry.glyphs[i].go:SetActive(false)end
   end
  end
 end
end

function UI.inkText(parent,name,value,size,w,h,x,y)
 local go,rt=UI.node(parent,name,false);rt.sizeDelta=UI.V2(w,h);rt.anchoredPosition=UI.V2(x,y)
 local t=go:AddComponent(typeof(UnityEngine.UI.Text));t.font=GetInkFont();t.text=value;t.fontSize=size;t.color=UnityEngine.Color(.25,.18,.11,.9);t.alignment=UnityEngine.TextAnchor.MiddleCenter;t.raycastTarget=false;ApplyInkText(t);return t
end
function UI.showOath()
 local r=DR.phase1.rpg;if not r or not UI.P_book then return false end
 local B=UI.P_book;B.ritualGo:SetActive(false);UI.spread=4;B.left.go:SetActive(false);B.right.go:SetActive(false);B.hint.go:SetActive(false);B.skip.go:SetActive(false)
 UI.show(B,true);UI.state='book';UI.lockPlayer(DouyinActorService.GetLocalActor(),true)
 return r.OpenContract(false,function()
  UI.show(B,false);B.left.go:SetActive(true);B.right.go:SetActive(true);B.hint.go:SetActive(true);B.skip.go:SetActive(false)
  UI.enterPlay(DouyinActorService.GetLocalActor())
 end,B.book.rt)
end


